quickstart.code:
{
  "nodes": [
    {
      "parameters": {
        "path": "readaloud-demo",
        "responseMode": "lastNode"
      },
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [
        0,
        0
      ]
    },
    {
      "parameters": {
        "resource": "speech",
        "operation": "textToSpeech",
        "text": "Thanks for calling. How can I help you today?",
        "voice": "readaloud-default",
        "format": "mp3",
        "speed": 1
      },
      "name": "ReadAloud",
      "type": "n8n-nodes-readaloud.readAloud",
      "typeVersion": 1,
      "position": [
        250,
        0
      ],
      "credentials": {
        "readAloudApi": {
          "id": "<select your ReadAloud API credential>",
          "name": "ReadAloud API"
        }
      }
    },
    {
      "parameters": {
        "operation": "write",
        "fileName": "/path/to/allowed/folder/speech.mp3",
        "dataPropertyName": "data",
        "options": {}
      },
      "name": "Write Binary File",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [
        500,
        0
      ]
    }
  ],
  "connections": {
    "Webhook": {
      "main": [
        [
          {
            "node": "ReadAloud",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "ReadAloud": {
      "main": [
        [
          {
            "node": "Write Binary File",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}
